22:     internal class IdentityManager : IIdentityManager
23:     {
24:         internal const string k_UnityAnalyticsInstallationIdKey = "UnityAnalyticsInstallationId";
25:         internal const string k_UnityAnalyticsUserIdKey = "UnityAnalyticsUserId";
26: 
27:         readonly IPlayerId m_PlayerId;
28:         readonly IExternalUserId m_ExternalIdProvider;
29:         readonly IPersistence m_Persistence;
30: 
31:         bool m_Initialized;
32: 
33:         public string UserId { get; private set; }
34:         public string InstallId { get; private set; }
35:         public string PlayerId { get { return m_PlayerId?.PlayerId; } }
36:         public string ExternalId { get; private set; }
37: 
38:         public bool IsNewPlayer { get; private set; }
39: 
40:         public event Action OnPlayerChanged;
41: 
42:         public IdentityManager(IInstallationId installId, IPlayerId playerId, IExternalUserId externalId, IPersistence persistence)
43:         {
44:             InstallId = installId.GetOrCreateIdentifier();
45:             m_PlayerId = playerId;
46:             m_ExternalIdProvider = externalId;
47:             m_Persistence = persistence;
48: 
49:             if (m_ExternalIdProvider != null)
50:             {
51:                 m_ExternalIdProvider.UserIdChanged += ExternalUserIdChanged;
52:                 ExternalId = m_ExternalIdProvider.UserId;
53:             }
54:             // Even though we'll deal with this properly if/when we Initialize, we need to set it up now
55:             // so that the Debug Panel will display the correct ID(s).
56:             UserId = !String.IsNullOrEmpty(ExternalId) ? ExternalId : InstallId;
57:         }
58: 
59:         public void Initialize()
60:         {
61:             if (!m_Initialized)
62:             {
63:                 string lastUserId = m_Persistence.LoadString(k_UnityAnalyticsUserIdKey);
64:                 bool migrating = false;
65:                 if (String.IsNullOrEmpty(lastUserId))
66:                 {
67:                     // Backwards compatibility while we phase out the old key.
68:                     lastUserId = m_Persistence.LoadString(k_UnityAnalyticsInstallationIdKey);
69:                     m_Persistence.ClearValue(k_UnityAnalyticsInstallationIdKey);
70:                     migrating = !String.IsNullOrEmpty(lastUserId);
71:                 }
72: 
73:                 if (m_ExternalIdProvider != null)
74:                 {
75:                     ExternalId = m_ExternalIdProvider.UserId;
76:                 }
77: 
78:                 UserId = String.IsNullOrEmpty(ExternalId) ? InstallId : ExternalId;
79: 
80:                 // "Have we initialized as a different user than last time?"
81:                 IsNewPlayer = String.IsNullOrEmpty(lastUserId) || !lastUserId.Equals(UserId, StringComparison.Ordinal);
82:                 if (IsNewPlayer || migrating)
83:                 {
84:                     m_Persistence.SaveValue(k_UnityAnalyticsUserIdKey, UserId);
85:                 }
86: 
87:                 m_Initialized = true;
88:             }
89:         }
90: 
91:         private void ExternalUserIdChanged(string newName)
92:         {
93:             // If we have not yet been initialized, then Initialize() above will examine
94:             // the initial state and handle it there. This method is for runtime/post-first-enablement changes.
95:             if (m_Initialized)
96:             {
97:                 // Changing the ID at runtime/after initialisation.
98: 
99:                 if (UserId.Equals(newName, StringComparison.Ordinal))
100:                 {
101:                     // Do nothing, you have not changed the ID.
102:                     // Potentially weird edge case: what if they set the external ID to be the installation ID?
103:                     // Would that make a blind bit of difference to anything? No, but it could be confusing.
104:                 }
105:                 else
106:                 {
107:                     if (String.IsNullOrEmpty(newName))
108:                     {
109:                         // We are clearing our externalID and falling back to installationID.
110:                         // An externalID was set before but is null now.
111:                         UserId = InstallId;
112:                     }
113:                     else if (String.IsNullOrEmpty(ExternalId))
114:                     {
115:                         // We are changing from installationID to externalID.
116:                         // An externalID was not set before but is set now.
117:                         UserId = newName;
118:                     }
119:                     else if (!ExternalId.Equals(newName, StringComparison.Ordinal))
120:                     {
121:                         // We have changed our externalID to a different externalID.
122:                         UserId = newName;
123:                     }
124: 
125:                     m_Persistence.SaveValue(k_UnityAnalyticsUserIdKey, UserId);
126:                     ExternalId = newName;
127:                     IsNewPlayer = true;
128: 
129:                     OnPlayerChanged?.Invoke();
130:                 }
131:             }
132:             else
133:             {
134:                 // Even though we'll deal with this properly if/when we Initialize, we need to set it up now
135:                 // so that the Debug Panel will display the correct ID(s).
136:                 ExternalId = newName;
137:                 UserId = !String.IsNullOrEmpty(ExternalId) ? ExternalId : InstallId;
138:             }
139:         }

