174:         // Shared by the Android and Apple branches: fetches each Firebase
175:         // identifier the remote connections settings allow, caching non-null results.
176:         internal async Task<(string? appInstanceId, string? firebaseSessionId, string? firebaseAppId)> FetchEnabledFirebaseIdsAsync(IFirebaseAnalyticsClient client)
177:         {
178:             var enabledAttributes = EnabledAttributes;
179:             string? appInstanceId = null;
180:             string? firebaseSessionId = null;
181:             string? firebaseAppId = null;
182:             // Google Analytics seems to bind its ids at configure: before it, the app id is the plist fallback, the app
183:             // instance id can still be reset, and the session id is always null. Ids are cached only once configured,
184:             // as Google Analytics seems to keep the first configured app's ids until relaunch (observed with Firebase
185:             // iOS SDK 10.29 and 12.19). Android has no configure step.
186:             var defaultAppConfigured = !(client is IFirebaseDefaultAppState state) || state.IsDefaultAppConfigured;
187:             if (enabledAttributes.Contains(ConnectionsSettingsClient.AppInstanceIdKey))
188:             {
189:                 appInstanceId = m_CachedAppInstanceId ?? await client.FetchAppInstanceIdAsync();
190:                 if (defaultAppConfigured)
191:                 {
192:                     m_CachedAppInstanceId ??= appInstanceId;
193:                 }
194:             }
195:             // Not requested before configure, where it is always null.
196:             if (enabledAttributes.Contains(ConnectionsSettingsClient.FirebaseSessionIdKey) && defaultAppConfigured && !m_FirebaseSessionIdTimedOut)
197:             {
198:                 if (m_CachedFirebaseSessionId == null)
199:                 {
200:                     var (sessionId, timedOut) = await client.FetchSessionIdAsync();
201:                     m_CachedFirebaseSessionId = sessionId;
202:                     // A null session id that hit the native timeout is cached, so later identities skip the 2 s wait.
203:                     m_FirebaseSessionIdTimedOut = (sessionId == null) && timedOut;
204:                 }
205:                 firebaseSessionId = m_CachedFirebaseSessionId;
206:             }
207:             if (enabledAttributes.Contains(ConnectionsSettingsClient.FirebaseAppIdKey))
208:             {
209:                 firebaseAppId = m_CachedFirebaseAppId ?? await client.FetchAppIdAsync();
210:                 if (defaultAppConfigured)
211:                 {
212:                     m_CachedFirebaseAppId ??= firebaseAppId;
213:                 }
214:             }
215:             return (appInstanceId, firebaseSessionId, firebaseAppId);

