188:         const string k_InsightsIngestUrl = "https://prd.insights.analytics.unity3d.com/v1/ingest/producer";
189: 
190:         internal static void Forward(IAPSDKEvent iaps)
191:         {
192:             var body = PurchaseEventProtobufWriter.Write(iaps);
193: 
194:             // UNITY_INSIGHTS_REQUIREMENTS_API is a versionDefine (Unity >= 6000.7.0a7):
195:             // those Editors provide the RequiresInsights attribute (declared in the
196:             // package's Editor assembly), which guarantees the Insights module is kept
197:             // in player builds, so events can go through the module.
198:             // ENABLE_CLOUD_SERVICES_ENGINE_DIAGNOSTICS gates the Insights module
199:             // itself — it is set per-platform, so platforms without Insights (e.g.
200:             // Linux) fall back to POSTing to the Insights gateway directly.
201: #if UNITY_INSIGHTS_REQUIREMENTS_API && ENABLE_CLOUD_SERVICES_ENGINE_DIAGNOSTICS
202:             ForwardModule(body);
203: #else
204:             ForwardGateway(body);
205: #endif
206:         }
207: 
208: #if UNITY_INSIGHTS_REQUIREMENTS_API && ENABLE_CLOUD_SERVICES_ENGINE_DIAGNOSTICS
209:         static void ForwardModule(byte[] body)
210:         {
211:             // EngineDiagnostics.LogEvent takes a ReadOnlySpan<char>, so the
212:             // proto3 binary body is base64-encoded to fit a text channel
213:             // losslessly. The receiving side base64-decodes back to the same
214:             // bytes that ForwardGateway POSTs.
215:             EngineDiagnostics.LogEvent((int)InsightsEventType.IapSdk, Convert.ToBase64String(body));
216:         }
217: #endif
218: 
219:         static void ForwardGateway(byte[] body)
220:         {
221:             var request = new UnityWebRequest(k_InsightsIngestUrl, UnityWebRequest.kHttpVerbPOST)
222:             {
223:                 uploadHandler = new UploadHandlerRaw(body),
224:                 downloadHandler = new DownloadHandlerBuffer()
225:             };
226:             request.SetRequestHeader("Content-Type", "application/x-protobuf");
227:             request.SetRequestHeader("Accept", "application/x-protobuf");
228:             request.SetRequestHeader("X-Tenant", "iapSdk");
229:             request.SetRequestHeader("X-Schema-Name", "insights.producers.iapsdk.v1alpha1.IAPSDKEvent");
230:             request.SetRequestHeader("X-Schema-Version", "1");
231:             request.SetRequestHeader("X-Proto-Sdk-Version", "1");
232:             request.SetRequestHeader("X-SDK-Release-Version", IAPVersion.Current);
233: 
234:             var op = request.SendWebRequest();
235:             op.completed += _ =>
236:             {
237:                 request.Dispose();
238:             };
239:         }

