14:     // Serializes a proto-faithful Insights.Models.IAPSDKEvent to canonical
15:     // proto3 binary wire format. See
16:     // Schemas~/insights/producers/iapsdk/v1alpha1/iap_sdk_event.proto for
17:     // the schema this output must parse against.
18:     //
19:     // Proto3 wire conventions enforced here:
20:     //   - tag = (field_number << 3) | wire_type, encoded as a varint
21:     //   - wire types used: 0 (varint) for ints/enums, 2 (LEN) for strings/messages
22:     //   - default values omitted (empty string, 0, unspecified enum, empty list, null message)
23:     //   - google.protobuf.Timestamp: nested message { int64 seconds = 1, int32 nanos = 2 }
24:     //   - oneof: only the active variant is emitted
25:     //   - int32/int64: standard varint of the two's-complement bit pattern
26:     //     (no ZigZag — that's only for sintN, which the schema doesn't use)
27:     internal static class PurchaseEventProtobufWriter
28:     {
29:         const int WireVarint = 0;
30:         const int WireLen = 2;
31: 
32:         public static byte[] Write(IAPSDKEvent e)
33:         {
34:             using var ms = new MemoryStream(512);
35:             SerializeIaps(ms, e);
36:             return ms.ToArray();
37:         }
