39:         static void SerializeIaps(Stream s, IAPSDKEvent e)
40:         {
41:             WriteTimestampField(s, 1, e.Timestamp);
42:             WriteOptionalString(s, 2, e.EventUuid);
43:             WriteOptionalString(s, 3, e.SessionId);
44:             WriteOptionalString(s, 4, e.FirebaseSessionId);
45:             WriteOptionalString(s, 5, e.ProjectId);
46:             WriteOptionalString(s, 6, e.EnvironmentId);
47:             WriteOptionalString(s, 7, e.IapSdkVersion);
48:             WriteOptionalString(s, 8, e.EngineVersion);
49: 
50:             if (e.UnityConsentStateAdsIntent != ConsentState.Unspecified)
51:             {
52:                 WriteVarintField(s, 9, (long)e.UnityConsentStateAdsIntent);
53:             }
54:             if (e.UnityConsentStateAnalyticsIntent != ConsentState.Unspecified)
55:             {
56:                 WriteVarintField(s, 10, (long)e.UnityConsentStateAnalyticsIntent);
57:             }
58: 
59:             if (e.UnityIdentities != null)
60:             {
61:                 WriteMessageField(s, 11, sub => WritePlayerIdentity(sub, e.UnityIdentities!));
62:             }
63:             if (e.DeviceInfo != null)
64:             {
65:                 WriteMessageField(s, 12, sub => WriteDeviceInfo(sub, e.DeviceInfo!));
66:             }
67:             if (e.Reporting != null)
68:             {
69:                 WriteMessageField(s, 13, sub => WriteReporting(sub, e.Reporting!));
70:             }
71: 
72:             if (e.InstallationTimestamp.HasValue)
73:             {
74:                 WriteTimestampField(s, 14, e.InstallationTimestamp.Value);
75:             }
76: 
77:             if (e.Store != Store.Unspecified)
78:             {
79:                 WriteVarintField(s, 15, (long)e.Store);
80:             }
81: 
82:             if (e.Order != null)
83:             {
84:                 WriteMessageField(s, 16, sub => WriteOrder(sub, e.Order!));
85:             }
