87:             WriteEventVariant(s, e.EventData);
88: 
89:             WriteOptionalString(s, 21, e.ApplicationVersion);
90:             WriteOptionalString(s, 24, e.ImpressionId);
91:             WriteOptionalString(s, 100, e.FirebaseAppId);
92:             WriteOptionalString(s, 101, e.InstallMode);
