97:             switch (variant)
98:             {
99:                 case PurchaseIntentStartEvent:
100:                     WriteMessageField(s, 17, _ => { });
101:                     break;
102:                 case PurchasePaidEvent paid:
103:                     WriteMessageField(s, 18, sub => WriteStorePayload(sub, paid.Payload));
104:                     break;
105:                 case PurchaseFailedEvent failed:
106:                     WriteMessageField(s, 19, sub => WritePurchaseFailed(sub, failed));
107:                     break;
108:                 case PurchaseFulfilledEvent fulfilled:
