240:             WriteOptionalString(s, 3, p.UserId);
241:             WriteOptionalString(s, 4, p.AnalyticsId);
242:             WriteOptionalString(s, 5, p.Idfa);
243:             WriteOptionalString(s, 6, p.Gaid);
244:             WriteOptionalString(s, 7, p.Idfv);
