249:         // == Field-type helpers ==
250: 
251:         // google.protobuf.Timestamp wire format: nested message with
252:         // int64 seconds (field 1) and int32 nanos (field 2). Skip the inner
253:         // scalars when they're 0 per proto3 default-skip rules, but always
254:         // emit the outer message field so the timestamp's presence is
255:         // signalled (length-zero message body is valid).
256:         static void WriteTimestampField(Stream s, int fieldNumber, DateTime dt)
257:         {
258:             var utc = dt.Kind == DateTimeKind.Utc ? dt : dt.ToUniversalTime();
259:             var unixEpochTicks = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc).Ticks;
260:             var elapsedTicks = utc.Ticks - unixEpochTicks;
261:             var seconds = elapsedTicks / TimeSpan.TicksPerSecond;
262:             var subSecondTicks = elapsedTicks - seconds * TimeSpan.TicksPerSecond;
263:             var nanos = (int)(subSecondTicks * 100); // 100ns ticks → 1ns
264: 
265:             WriteMessageField(s, fieldNumber, sub =>
266:             {
267:                 if (seconds != 0)
268:                 {
269:                     WriteVarintField(sub, 1, seconds);
270:                 }
271:                 if (nanos != 0)
272:                 {
273:                     WriteVarintField(sub, 2, nanos);
274:                 }
275:             });
276:         }
277: 
278:         static void WriteOptionalString(Stream s, int fieldNumber, string? value)
279:         {
280:             if (string.IsNullOrEmpty(value)) return;
281:             WriteString(s, fieldNumber, value!);
282:         }
283: 
284:         static void WriteString(Stream s, int fieldNumber, string value)
285:         {
286:             var bytes = Encoding.UTF8.GetBytes(value);
287:             WriteTag(s, fieldNumber, WireLen);
288:             WriteVarint(s, (ulong)bytes.Length);
289:             s.Write(bytes, 0, bytes.Length);
290:         }
291: 
292:         static void WriteVarintField(Stream s, int fieldNumber, long value)
293:         {
294:             WriteTag(s, fieldNumber, WireVarint);
295:             WriteVarint(s, (ulong)value);
296:         }
297: 
298:         static void WriteUInt64Field(Stream s, int fieldNumber, ulong value)
299:         {
300:             WriteTag(s, fieldNumber, WireVarint);
301:             WriteVarint(s, value);
302:         }
303: 
304:         // Two-pass for length-prefixed messages: serialize body to a sub-
305:         // stream so we can prefix with its length. Keeps the writer simple
306:         // at the cost of one extra MemoryStream per nested message.
307:         static void WriteMessageField(Stream s, int fieldNumber, Action<Stream> writeBody)
308:         {
309:             using var sub = new MemoryStream();
310:             writeBody(sub);
311:             WriteTag(s, fieldNumber, WireLen);
312:             WriteVarint(s, (ulong)sub.Length);
313:             sub.WriteTo(s);
314:         }
315: 
316:         // == Primitive encoders ==
317: 
318:         static void WriteTag(Stream s, int fieldNumber, int wireType)
319:         {
320:             WriteVarint(s, ((ulong)fieldNumber << 3) | (uint)wireType);
321:         }
322: 
323:         static void WriteVarint(Stream s, ulong value)
324:         {
325:             while (value >= 0x80)
326:             {
327:                 s.WriteByte((byte)((value & 0x7F) | 0x80));
328:                 value >>= 7;
329:             }
330:             s.WriteByte((byte)value);
331:         }
332:     }
