8:     // Ambient impression_id (IAPSDKEvent field 24) for the purchase journey
9:     // running on the current async flow. Backed by AsyncLocal, so the id passes
10:     // through synchronous calls and awaits — including developer-overridden
11:     // interfaces — without leaking into concurrent flows. It is dropped wherever
12:     // the call chain breaks (native callbacks, UI clicks, Update), which is
13:     // accepted.
14:     //
15:     // For Payment Provider purchases the SDK sends no event after intent-start:
16:     // the backend sends paid/fulfilled from the order, so the order must carry
17:     // this same id (see PaymentProviderImpl.InitiateOrder).
18:     //
19:     // Scopes must be entered inside an async method, or inside a synchronous
20:     // method that disposes before returning: an AsyncLocal assigned inside an
21:     // async method never reaches its caller.
22:     //
23:     // A journey ends at its outcome. Outcomes are reported inside EnterOutcome
24:     // (PurchaseUseCase does this for every store), which keeps the id readable
25:     // for the outcome's own events but stops EnterOrJoin joining it: a purchase
26:     // a handler starts — directly or after an await — begins its own journey.
27:     //
28:     // Only purchase entry points start or join a journey (EnterOrJoin). Every
29:     // other public service API that does store or async work runs inside
30:     // EnterNone, so a caller's id can't reach the outcomes of other transactions
31:     // it delivers (e.g. a handler's FetchPurchases). A reflection test
32:     // (ImpressionJourneyClassificationTests) makes every public service method
33:     // pick one, or be listed as inert.
34:     internal sealed class ImpressionScope : IImpressionScope
35:     {
36:         // The only instance: each instance keeps its own id, so an id set through one
37:         // instance can't be read through another.
38:         internal static readonly ImpressionScope Shared = new ImpressionScope();
39: 
40:         readonly AsyncLocal<Journey?> m_Current = new AsyncLocal<Journey?>();
41: 
42:         ImpressionScope() { }
43: 
44:         public string? Current => m_Current.Value?.Id;
45: 
46:         // Starts a new journey with a fresh id, whether or not one is active.
47:         public IDisposable Enter() => Enter(NewId());
48: 
49:         // Sets id for the scope's duration. Dispose restores the previous value,
50:         // so nested scopes unwind correctly.
51:         public IDisposable Enter(string id) => Set(new Journey(id, joinable: true));
52: 
53:         // Joins the active scope if it can be joined (the returned disposable
54:         // does nothing); otherwise enters a new scope with a freshly minted id.
55:         public IDisposable EnterOrJoin()
56:         {
57:             return m_Current.Value is { Joinable: true } ? NoOp.Instance : Enter();
58:         }
59: 
60:         // Marks the active journey as reporting its outcome for the scope's
61:         // duration: Current is unchanged, but EnterOrJoin no longer joins it.
62:         public IDisposable EnterOutcome()
63:         {
64:             var current = m_Current.Value;
65:             return current is { Joinable: true } ? Set(new Journey(current.Id, joinable: false)) : NoOp.Instance;
66:         }
67: 
68:         // Runs the scope's duration with no journey: Current is null and EnterOrJoin
69:         // mints a new id. For public APIs that are never part of a purchase journey,
70:         // so a caller's id can't reach the work they start.
71:         public IDisposable EnterNone()
72:         {
73:             return m_Current.Value is null ? NoOp.Instance : Set(null);
74:         }
75: 
76:         IDisposable Set(Journey? journey)
77:         {
78:             var previous = m_Current.Value;
79:             m_Current.Value = journey;
80:             return new Restore(this, previous);
81:         }
82: 
83:         static string NewId() => Guid.NewGuid().ToString();
84: 
85:         sealed class Journey
86:         {
87:             internal readonly string Id;
88:             internal readonly bool Joinable;
89: 
90:             internal Journey(string id, bool joinable)
91:             {
92:                 Id = id;
93:                 Joinable = joinable;
94:             }
95:         }
96: 
97:         sealed class Restore : IDisposable
98:         {
99:             readonly ImpressionScope m_Scope;
100:             readonly Journey? m_Previous;
101:             bool m_Disposed;
102: 
103:             internal Restore(ImpressionScope scope, Journey? previous)
104:             {
105:                 m_Scope = scope;
106:                 m_Previous = previous;
107:             }
108: 
109:             public void Dispose()
110:             {
111:                 if (m_Disposed)
112:                     return;
113: 
114:                 m_Disposed = true;
115:                 m_Scope.m_Current.Value = m_Previous;
116:             }

