15: {
16:     [NativeHeader("Modules/Insights/EngineDiagnostics.h")]
17:     [ExcludeFromDocs]
18:     public static class EngineDiagnostics
19:     {
20:         public static readonly bool IsEnabled = IsInsightsEnabled();
21:         static extern bool IsInsightsEnabled();
22: 
23:         [NoAutoStaticsCleanup] // native sets this once at startup and native state survives code reload, so the managed value must persist to stay in sync
24:         public static bool IsInitialized
25:         {
26:             // So this warrants some explanations...
27:             // The native side will call the setter once we're initialized, but if we just mark it
28:             // as RequiredByNativeCode, we force it to be included always which prevents stripping
29:             // of the Insights module. Thus we also need to mark it as optional. But if we do that
30:             // without having any managed code calling it, then it will be stripped. That's where
31:             // DynamicDependency comes in. We're basically telling the linker that if the getter is
32:             // used in any in the player build, to keep the setter around even though it's not used
33:             // anywhere on the managed side.
34:             [DynamicDependency("set_IsInitialized", typeof(EngineDiagnostics))]
35:             get;
36:             [RequiredByNativeCode(Optional = true)]
37:             private set;
38:         }
39: 
40:         public static extern bool IsEventAllowed(int eventType);
41: 
42:         // Pushed by native on OnConfigurationReady, and read from the callback threads the
43:         // ManagedCapture hooks run on. Only ever replaced, never mutated, so readers need no lock.
44:         [NoAutoStaticsCleanup] static int[] s_BlockedEventTypes;
45: 
46:         [RequiredByNativeCode(Optional = true)]
47:         internal static void SetBlockedEventTypes(int[] blockedEventTypes)
48:         {
49:             // Empty normalizes to null so the hook's check is a single null test.
50:             Volatile.Write(ref s_BlockedEventTypes,
51:                 blockedEventTypes != null && blockedEventTypes.Length > 0 ? blockedEventTypes : null);
52:         }
53: 
54:         // The setter is only ever called from native, so it needs a managed anchor the linker keeps.
55:         // [Preserve] would do this unconditionally, but it's banned in engine modules because it also
56:         // stops the whole module from being stripped when nothing uses Insights at all — DynamicDependency
57:         // only keeps the setter alive when this method itself is already reachable.
58:         [DynamicDependency("SetBlockedEventTypes", typeof(EngineDiagnostics))]
59:         [MethodImpl(MethodImplOptions.AggressiveInlining)]
60:         internal static bool IsEventTypeBlocked(int eventType)
61:         {
62:             var blockedEventTypes = Volatile.Read(ref s_BlockedEventTypes);
63:             if (blockedEventTypes == null)
64:                 return false;
65: 
66:             for (int i = 0; i < blockedEventTypes.Length; i++)
67:             {
68:                 if (blockedEventTypes[i] == eventType)
69:                     return true;
70:             }
71:             return false;
72:         }
73: 
74:         [NativeMethod(IsThreadSafe = true)]
75:         public static extern void LogEvent(int eventType, ReadOnlySpan<char> eventData, bool immediate = false);
76: 
77:         [NativeMethod(IsThreadSafe = true)]
78:         internal static extern void LogEventDeferred(int eventType, ReadOnlySpan<char> eventData, bool immediate = false);
79:     }

