24:     static class AppInstallInfo
25:     {
26:         // Install timestamp is immutable for the lifetime of the install, so
27:         // cache it after the first lookup to avoid repeating JNI calls (Android)
28:         // or disk I/O (iOS) on every Insights event emission. Lazy<T> with
29:         // ExecutionAndPublication mode provides formal thread-safety guarantees
30:         // even though PurchaseEventEmitter's constructor pre-warms the cache
31:         // on the main thread (see PurchaseEventEmitter.cs constructor).
32:         static Lazy<DateTime?> s_LazyTimestamp = new(FetchInstallTimestamp, LazyThreadSafetyMode.ExecutionAndPublication);
33: 
34:         [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
35:         static void ResetStaticsOnLoad()
36:         {
37:             s_LazyTimestamp = new Lazy<DateTime?>(FetchInstallTimestamp, LazyThreadSafetyMode.ExecutionAndPublication);
38:         }
39: 
40:         internal static DateTime? GetInstallTimestamp() => s_LazyTimestamp.Value;
41: 
42:         static DateTime? FetchInstallTimestamp()
43:         {
44: #if UNITY_ANDROID && !UNITY_EDITOR
45:             try
46:             {
47:                 using var activity = UnityActivity.GetCurrentActivity();
48:                 using var packageManager = activity.Call<AndroidJavaObject>("getPackageManager");
49:                 var packageName = activity.Call<string>("getPackageName");
50:                 using var packageInfo = packageManager.Call<AndroidJavaObject>("getPackageInfo", packageName, 0);
51:                 var firstInstallTimeMs = packageInfo.Get<long>("firstInstallTime");
52:                 return DateTimeOffset.FromUnixTimeMilliseconds(firstInstallTimeMs).UtcDateTime;
53:             }
54:             catch
55:             {
56:                 return null;
57:             }
58: #elif UNITY_IOS && !UNITY_EDITOR
59:             try
60:             {
61:                 // persistentDataPath is a directory, use Directory.GetCreationTimeUtc
62:                 // for semantic precision (File.* also works but is for files).
63:                 var creationTime = Directory.GetCreationTimeUtc(Application.persistentDataPath);
64:                 // .NET returns 1601-01-01T00:00:00Z (NOT DateTime.MinValue which is
65:                 // 0001-01-01) when the path does not exist or is inaccessible.
66:                 return creationTime.Year > 1601 ? (DateTime?)creationTime : null;
67:             }
68:             catch
69:             {
70:                 return null;
71:             }
72: #else
73:             return null;
74: #endif
